def transform(grid):
    """Draw marker-aligned rays and recolor the first object each hits.

    A marker on the top/bottom edge launches vertically; one on the left/right
    edge launches horizontally. Each ray changes the first 4-connected color-2
    object it encounters, while the ray itself continues across the grid.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Label all color-2 connected components so a ray hit recolors the whole
    # object, not just its cells on the ray.
    seen = set()
    components = []
    component_at = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            idx = len(components)
            components.append(cells)
            for cell in cells:
                component_at[cell] = idx

    selected = set()
    row_rays = set()
    col_rays = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                continue
            if r == 0:
                col_rays.add(c)
                scan = ((y, c) for y in range(1, h))
            elif r == h - 1:
                col_rays.add(c)
                scan = ((y, c) for y in range(h - 2, -1, -1))
            elif c == 0:
                row_rays.add(r)
                scan = ((r, x) for x in range(1, w))
            elif c == w - 1:
                row_rays.add(r)
                scan = ((r, x) for x in range(w - 2, -1, -1))
            else:
                continue
            for y, x in scan:
                if grid[y][x] == 2:
                    selected.add(component_at[(y, x)])
