def transform(grid):
    """Trace inward rays from border 1s and recolor their first 2 object.

    The paired border rays are drawn as complete rows/columns. A marker also
    recolors an immediately nearby object (within two Manhattan steps), as in
    the demo where the bottom marker's nearest side-adjacent block is selected.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    comps, comp_at = [], {}
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            idx = len(comps)
            comps.append(cells)
            for cell in cells: comp_at[cell] = idx

    markers = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    selected = set()
    row_lines, col_lines = set(), set()
    for r,c in markers:
        if r == 0:
            col_lines.add(c); scan = ((y,c) for y in range(1,h))
        elif r == h-1:
            col_lines.add(c); scan = ((y,c) for y in range(h-2,-1,-1))
        elif c == 0:
            row_lines.add(r); scan = ((r,x) for x in range(1,w))
        elif c == w-1:
            row_lines.add(r); scan = ((r,x) for x in range(w-2,-1,-1))
        else:
            continue
        for y,x in scan:
            if grid[y][x] == 2:
                selected.add(comp_at[(y,x)])
                break
        # Close side gaps immediately beside the marker itself.
        for i,cells in enumerate(comps):
            if any(abs(y-r)+abs(x-c) <= 2 for y,x in cells):
                selected.add(i)

    for i in selected:
        for r,c in comps[i]: out[r][c] = 1
    for r in row_lines: out[r] = [1]*w
    for c in col_lines:
        for r in range(h): out[r][c] = 1
    return out
