{
 "content": "from collections import deque


def transform(grid):
    """Cast straight rays from boundary 1-markers; repaint all hit objects.

    Top/bottom markers define vertical lines; left/right markers define
    horizontal lines. Recolor every 4-connected color-2 component touched by
    any such line, then draw the complete lines in color 1.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    horizontal = {r for r in range(h) for c in range(w)
                  if grid[r][c] == 1 and c in (0, w - 1)}
    vertical = {c for r in range(h) for c in range(w)
                if grid[r][c] == 1 and r in (0, h - 1)}

    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            hit = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y in horizontal or x in vertical:
                    hit = True
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if hit:
                for y, x in cells:
                    out[y][x] = 1

    for r in horizontal:
        out[r] = [1] * w
    for c in vertical:
        for r in range(h):
            out[r][c] = 1
    return out
